import{z as n,x as A,o as B,c as p,q as l,j as i,D as t,d as a,s as o,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const M=JSON.parse('{"title":"E4M3 / E5M2","description":"","frontmatter":{"title":"E4M3 / E5M2","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/fp8-formats.md","filePath":"llm/fp8-formats.md","lastUpdated":1791063341000}'),F={name:"llm/fp8-formats.md"};function C(d,E,m,P,T,f){const r=A("Mermaid");return B(),p("div",null,[E[2]||(E[2]=l('<h1 id="e4m3-e5m2" tabindex="-1">E4M3 / E5M2 <a class="header-anchor" href="#e4m3-e5m2" aria-label="Permalink to &quot;E4M3 / E5M2&quot;">​</a></h1><div class="epigraph"><p>FP8 仍是浮点：指数决定动态范围，尾数决定精度。E4M3 多给尾数，E5M2 多给指数。同一 8 bit，对准的是计算核，不是 GPTQ 那种整数格子。</p><footer>—— 对照 NVIDIA/Intel/ARM 的 FP8 白皮书与 OCP 8-bit 浮点约定；训练配方另见通信 dtype</footer></div><p><a href="/llm/nf4-quantile">NF4</a> 是存储用的分位整数码本。本课 <strong>E4M3 / E5M2</strong> 是 8-bit 浮点格式，面向 Tensor Core 上的乘加。缺口：它们是非均匀（指数编码），但不是学出来的码本；溢出、NaN、以及缩放（loss scale / 逐块 scale）是一等公民。<a href="/llm/accelerator-comparison-method">加速器对比</a> 里「有没有 FP8 核」指这一对，不是 NF4。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>E4M3：4 bit 指数、3 bit 尾数，精度相对好，动态范围窄，易溢出，适合需要准的前向权重/激活。E5M2：5 bit 指数、2 bit 尾数，范围更像 FP16 的缩小版，精度更糙，常放梯度或需要范围的张量。两者都是 8 bit，不能混用同一解释。</p><p><span class="marginnote">术语翻译：浮点数就是二进制的科学计数法——指数管「数量级能到多大、多小」，尾数管「这个量级里有几位有效数字」。E4M3 花 4 位存数量级、3 位存有效数字；E5M2 反过来。一个偏精度、一个偏范围，名字本身就是配方。</span></p><p>没有逐块或逐张量缩放时，Transformer 的激活离群会把 E4M3 打进 inf。FP8 训练是「格式 + 缩放策略 + 核」，缺一不可。问题是 <strong>把哪类张量放进哪一格式</strong>，以及与 PTQ INT8 的关系：FP8 常走训练/推理的原生核，INT8 常走事后量化。</p><p><span class="marginnote">OCP 与厂商白皮书对 E4M3 的 NaN / inf 行为有具体约定（有的变体几乎不用 inf）。实现必须跟核，不要假设 IEEE FP16 的语义缩小。本课不编造未写入公开格式文档的 bit 图案。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>训练：前向 E4M3、反向梯度 E5M2 是常见分工（以你用的框架默认与论文配方为准，换代会变）。必须有溢出监控与缩放更新。推理：权重、激活都 FP8 可吃 Tensor Core；KV 是否 FP8 另算，精度与长度敏感。</p><p>与 INT PTQ：FP8 推理往往是训练就在 FP8 或 QAT；把 FP16 模型事后「铸」成 FP8 仍要校准尺度，近似 W8A8，但格子是浮点不是均匀 INT。不要把 GPTQ 的 4-bit 整数检查点当成 E4M3。</p>',11)),(B(),i(s,null,{default:t(()=>[o(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20E43%5B%22E4M3%20%E5%A4%9A%E5%B0%BE%E6%95%B0%22%5D%20--%3E%20FWD%5B%22%E5%89%8D%E5%90%91%20%2F%20%E9%9C%80%E7%B2%BE%E5%BA%A6%22%5D%0A%20%20E52%5B%22E5M2%20%E5%A4%9A%E6%8C%87%E6%95%B0%22%5D%20--%3E%20GRAD%5B%22%E6%A2%AF%E5%BA%A6%20%2F%20%E9%9C%80%E8%8C%83%E5%9B%B4%22%5D%0A%20%20SCALE%5B%22%E9%80%90%E5%9D%97%E6%88%96%E6%8D%9F%E5%A4%B1%E7%BC%A9%E6%94%BE%22%5D%20--%3E%20E43%0A%20%20SCALE%20--%3E%20E52%0A%20%20HW%5B%22FP8%20Tensor%20Core%22%5D%20--%3E%20E43%0A%20%20HW%20--%3E%20E52%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("p",null,[a("通信："),e("a",{href:"/llm/pretrain-comm"},"预训练通信"),a(" 的梯度 FP8 通信是另一开关，格式可能与计算 FP8 对齐，协议必须全集群一致。")],-1)),E[4]||(E[4]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=e("p",null,"浮点的非均匀来自指数：靠近零（正规数范围内）相对精度大约恒定（尾数 bit），而不是均匀 INT 的绝对台阶恒定。对近似对数动态范围的张量，这比 INT8 更省心；对已经平滑到良好范围的张量，INT8 可能更准或核更成熟。离群仍会占满指数的高端，该通道其余值下溢——平滑与混精并不过时。",-1)),(B(),i(s,null,{default:t(()=>[o(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20I8%5B%22INT8%EF%BC%9A%E5%9D%87%E5%8C%80%E5%8F%B0%E9%98%B6%EF%BC%8C%E7%BB%9D%E5%AF%B9%E9%97%B4%E9%9A%94%E6%81%92%E5%AE%9A%22%5D%20--%3E%20C1%5B%22%E5%B9%B3%E6%BB%91%E5%88%86%E5%B8%83%E5%8F%8B%E5%A5%BD%EF%BC%8C%E8%8C%83%E5%9B%B4%E5%9B%BA%E5%AE%9A%20%C2%B1127%22%5D%0A%20%20E43%5B%22E4M3%EF%BC%9A3%20%E4%BD%8D%E5%B0%BE%E6%95%B0%EF%BC%8C%E7%9B%B8%E5%AF%B9%E7%B2%BE%E5%BA%A6%E8%BF%91%E6%81%92%E5%AE%9A%22%5D%20--%3E%20C2%5B%22%E8%BF%91%E9%9B%B6%E6%9B%B4%E5%AF%86%EF%BC%8C%E8%8C%83%E5%9B%B4%E7%AA%84%EF%BC%8C%E6%98%93%E6%BA%A2%E5%87%BA%22%5D%0A%20%20E52%5B%22E5M2%EF%BC%9A5%20%E4%BD%8D%E6%8C%87%E6%95%B0%EF%BC%8C%E8%8C%83%E5%9B%B4%E8%BF%91%20FP16%20%E7%BC%A9%E5%B0%8F%E7%89%88%22%5D%20--%3E%20C3%5B%22%E8%8C%83%E5%9B%B4%E5%A4%A7%EF%BC%8C%E5%B0%BE%E6%95%B0%E7%B2%97%EF%BC%8C%E9%80%82%E5%90%88%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20C1%20--%3E%20RULE%5B%22%E6%8C%89%E5%BC%A0%E9%87%8F%E6%80%A7%E8%B4%A8%E6%8B%86%E6%A0%BC%E5%BC%8F%EF%BC%8C%E4%B8%8D%E5%81%9A%E4%B8%80%E5%88%80%E5%88%87%22%5D%0A%20%20C2%20--%3E%20RULE%0A%20%20C3%20--%3E%20RULE%0A"})]),fallback:t(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=l('<p><span class="marginnote">数字实例：3 位尾数意味着同一数量级内只能分辨约 8 档，相邻两档相对间隔约 12.5%；2 位尾数约 4 档、间隔约 25%。这就是 E5M2 「更糙」的直观含义——每格更稀，舍入误差更大，但它换来了 FP16 量级的表示范围。</span></p><p>E4M3 范围不够时不是「换 E5M2 就结束」，梯度要范围、权重要精度，拆张量类型才是机制。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在没有 FP8 核的加速器上用软件模拟当对比成绩。不要混用不同厂商的 FP8 变体检查点。不要把 FP8 与 INT8 的 PPL 差写成「8 bit 就是 8 bit」。下一课开始验收：误差度量，适用于 INT 与 FP 格子。</p><p><span class="marginnote">常见误区：以为「都是 8 bit，FP8 和 INT8 差不多，GPTQ 4-bit 检查点也能当 FP8 用」。格子的结构完全不同——整数是均匀码本，浮点是非均匀指数格；核、缩放策略、误差行为都不通用。混着比，得到的结论基本不可信。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>E4M3 偏精度，E5M2 偏范围；都是 8-bit 浮点核格式。</li><li>必须配缩放；离群照样溢出或下溢。</li><li>与 GPTQ/NF4 检查点不互换；与梯度 FP8 通信要对齐协议。</li><li>对比加速器时 FP8 是计算维，不是存储码本维。</li><li>出处：FP8 白皮书与 OCP 8-bit 浮点约定；框架训练配方。</li></ul>',7))])}const b=n(F,[["render",C]]);export{M as __pageData,b as default};
